mapper.select:
SELECT is_trans_payable, is_cash_card, linked_bank_code, account_num,
       card_brand, annual_fee, issue_date
FROM mock_card_info
WHERE ci = #{ci}
  AND card_id = #{cardId}

SELECT d.card_id, d.paid_dtime, d.trans_no, d.paid_amt, d.currency_code,
       d.merchant_name, d.merchant_regno, d.credit_fee_amt,
       d.total_install_cnt, d.cur_install_cnt, d.balance_amt, d.prod_type
FROM mock_card_bill_detail d
INNER JOIN mock_card_info c ON c.card_id = d.card_id
WHERE c.ci = #{ci}
  AND d.charge_month = #{chargeMonth}
ORDER BY d.paid_dtime, d.mock_bill_detail_id
LIMIT #{limit}
